89	/// FAST002
90	pub(crate) fn fastapi_non_annotated_dependency(
91	    checker: &mut Checker,
92	    function_def: &ast::StmtFunctionDef,
93	) {
94	    if !checker.semantic().seen_module(Modules::FASTAPI)
95	        || !is_fastapi_route(function_def, checker.semantic())
96	    {
97	        return;
98	    }
99	
100	    let mut updatable_count = 0;
101	    let mut has_non_updatable_default = false;
102	    let total_params =
103	        function_def.parameters.args.len() + function_def.parameters.kwonlyargs.len();
104	
105	    for parameter in function_def
106	        .parameters
107	        .args
108	        .iter()
109	        .chain(&function_def.parameters.kwonlyargs)
110	    {
111	        let needs_update = matches!(
112	            (&parameter.parameter.annotation, &parameter.default),
113	            (Some(_annotation), Some(default)) if is_fastapi_dependency(checker, default)
114	        );
115	
116	        if needs_update {
117	            updatable_count += 1;
118	            // Determine if it's safe to update this parameter:
119	            // - if all parameters are updatable its safe.
120	            // - if we've encountered a non-updatable parameter with a default value, it's no longer
121	            //   safe. (https://github.com/astral-sh/ruff/issues/12982)
122	            let safe_to_update = updatable_count == total_params || !has_non_updatable_default;
123	            create_diagnostic(checker, parameter, safe_to_update);
124	        } else if parameter.default.is_some() {
125	            has_non_updatable_default = true;
126	        }
127	    }
128	}
129	
130	fn is_fastapi_dependency(checker: &Checker, expr: &ast::Expr) -> bool {
131	    checker
132	        .semantic()
133	        .resolve_qualified_name(map_callable(expr))
134	        .is_some_and(|qualified_name| {
135	            matches!(
136	                qualified_name.segments(),
137	                [
138	                    "fastapi",
139	                    "Query"
140	                        | "Path"
141	                        | "Body"
142	                        | "Cookie"
143	                        | "Header"
144	                        | "File"
145	                        | "Form"
146	                        | "Depends"
147	                        | "Security"
148	                ]
149	            )
150	        })
151	}
152	
153	fn create_diagnostic(
154	    checker: &mut Checker,
155	    parameter: &ast::ParameterWithDefault,
156	    safe_to_update: bool,
157	) {
158	    let mut diagnostic = Diagnostic::new(
159	        FastApiNonAnnotatedDependency {
160	            py_version: checker.settings.target_version,
161	        },
162	        parameter.range,
163	    );
164	
165	    if safe_to_update {
166	        if let (Some(annotation), Some(default)) =
167	            (&parameter.parameter.annotation, &parameter.default)
168	        {
169	            diagnostic.try_set_fix(|| {
170	                let module = if checker.settings.target_version >= PythonVersion::Py39 {
171	                    "typing"
172	                } else {
173	                    "typing_extensions"
174	                };
175	                let (import_edit, binding) = checker.importer().get_or_import_symbol(
176	                    &ImportRequest::import_from(module, "Annotated"),
177	                    parameter.range.start(),
178	                    checker.semantic(),
179	                )?;
180	                let content = format!(
181	                    "{}: {}[{}, {}]",
182	                    parameter.parameter.name.id,
183	                    binding,
184	                    checker.locator().slice(annotation.range()),
185	                    checker.locator().slice(default.range())
186	                );
187	                let parameter_edit = Edit::range_replacement(content, parameter.range);
188	                Ok(Fix::unsafe_edits(import_edit, [parameter_edit]))
189	            });
190	        }
191	    } else {
192	        diagnostic.fix = None;
193	    }
194	
195	    checker.diagnostics.push(diagnostic);
196	}
